import json, itertools, sys, random, time
from collections import Counter

ROOT = '/repo/data/analysis/gw6'
PRIOR = '/private/tmp/claude-501/-repo/19d99f5c-a2a6-486b-8614-b36040777608/scratchpad/prior'
POS = ['GKP', 'DEF', 'MID', 'FWD']
NEED = {'GKP': 2, 'DEF': 5, 'MID': 5, 'FWD': 3}


def load(root):
    pool = {}
    for p in POS:
        for r in json.load(open(f'{root}/players-{p}.json')):
            pool[r['id']] = dict(id=r['id'], name=r['name'], pos=p, team=r['team'], price=r['price'],
                                 ep=r['ep_gw'], ep6=r['ep_total6'], ps=r['p_start'], unc=r['uncertainty'],
                                 notes=r.get('notes', ''), fx=r.get('fixtures', []))
    return pool


BLEND = load(ROOT)
PRIORP = load(PRIOR)

# verified selling prices (fpl my-team --gw 6, relayed by orchestrator)
SELL = {1: 6.0, 4: 8.0, 229: 6.1, 202: 4.9, 68: 6.0, 427: 7.9, 69: 6.0, 237: 5.8, 411: 15.5, 106: 7.8,
        249: 5.6, 497: 4.0, 481: 6.3, 445: 5.0, 423: 4.3}
SQUAD = list(SELL)
BANK = 0.0
assert abs(sum(SELL.values()) - 99.2) < 1e-6


def best_xi(ids, gw, pool):
    """exact: top GK, then mandatory 3 DEF/2 MID/1 FWD, then best 4 of the rest."""
    by = {p: sorted([i for i in ids if pool[i]['pos'] == p], key=lambda i: -pool[i]['ep'][gw]) for p in POS}
    xi = [by['GKP'][0]] + by['DEF'][:3] + by['MID'][:2] + by['FWD'][:1]
    rest = sorted(by['DEF'][3:] + by['MID'][2:] + by['FWD'][1:], key=lambda i: -pool[i]['ep'][gw])
    xi += rest[:4]
    tot = sum(pool[i]['ep'][gw] for i in xi)
    cap = max(xi, key=lambda i: pool[i]['ep'][gw])
    return xi, tot + pool[cap]['ep'][gw], cap


def score(ids, pool, gws=range(6)):
    return sum(best_xi(ids, g, pool)[1] for g in gws)


def legal(ids, pool):
    c = Counter(pool[i]['pos'] for i in ids)
    if any(c[p] != NEED[p] for p in POS):
        return False
    return max(Counter(pool[i]['team'] for i in ids).values()) <= 3


def bank_after(ids):
    out = [i for i in SQUAD if i not in ids]
    inn = [i for i in ids if i not in SQUAD]
    return round(BANK + sum(SELL[i] for i in out) - sum(BLEND[i]['price'] for i in inn), 1)


def fmt(ids, pool=BLEND):
    return ', '.join(f"{pool[i]['name']}({pool[i]['price']})" for i in ids)


def pruned(pool, keep=10):
    """keep a player unless `keep` cheaper-or-equal players beat his ep6."""
    out = []
    for p in POS:
        rows = sorted([r for r in pool.values() if r['pos'] == p], key=lambda r: (r['price'], -r['ep6']))
        for r in rows:
            n = sum(1 for q in rows if q['price'] <= r['price'] and q['ep6'] > r['ep6'])
            if n < keep and r['ep6'] > 2:
                out.append(r['id'])
    return out


def transfers(k, cand, pool=BLEND, limit_out=None, must_out=()):
    """all k-for-k swaps from SQUAD, legal + affordable; returns list of (gain6, gain_p, outs, ins, bank, gw68)."""
    base6 = score(SQUAD, BLEND)
    basep = score(SQUAD, PRIORP)
    res = []
    outs_space = [o for o in itertools.combinations(SQUAD, k) if all(m in o for m in must_out)]
    for outs in outs_space:
        posmult = Counter(BLEND[i]['pos'] for i in outs)
        keep = [i for i in SQUAD if i not in outs]
        budget = BANK + sum(SELL[i] for i in outs)
        per_pos = {p: [c for c in cand if BLEND[c]['pos'] == p and c not in SQUAD] for p in posmult}
        groups = []
        for p, n in posmult.items():
            groups.append(list(itertools.combinations(per_pos[p], n)))
        for combo in itertools.product(*groups):
            ins = [i for g in combo for i in g]
            if sum(BLEND[i]['price'] for i in ins) > budget + 1e-9:
                continue
            ids = keep + ins
            if not legal(ids, BLEND):
                continue
            g6 = score(ids, BLEND) - base6
            gp = score(ids, PRIORP) - basep
            res.append((round(g6, 3), round(gp, 3), outs, tuple(ins), bank_after(ids),
                        round(score(ids, BLEND, range(3)) / 3, 2)))
    res.sort(key=lambda t: -t[0])
    return res


def wildcard(pool, budget, gws=range(6), starts=12, seed=0, cand=None, protect=()):
    rng = random.Random(seed)
    cand = cand or pruned(pool, 12)
    bypos = {p: [c for c in cand if pool[c]['pos'] == p] for p in POS}
    best = None
    for s in range(starts):
        # random greedy start
        while True:
            ids = []
            for p in POS:
                ids += rng.sample(bypos[p], NEED[p])
            ids = list(dict.fromkeys(list(protect) + [i for i in ids if i not in protect]))
            c = Counter(pool[i]['pos'] for i in ids)
            if all(c[p] == NEED[p] for p in POS) and legal(ids, pool) and sum(pool[i]['price'] for i in ids) <= budget:
                break
        cur = score(ids, pool, gws)
        improved = True
        while improved:
            improved = False
            # single swaps
            bestmove = None
            for o in ids:
                if o in protect:
                    continue
                for n in bypos[pool[o]['pos']]:
                    if n in ids:
                        continue
                    nid = [n if i == o else i for i in ids]
                    if sum(pool[i]['price'] for i in nid) > budget + 1e-9 or not legal(nid, pool):
                        continue
                    sc = score(nid, pool, gws)
                    if sc > cur + 1e-9 and (bestmove is None or sc > bestmove[0]):
                        bestmove = (sc, nid)
            if bestmove:
                cur, ids = bestmove
                improved = True
                continue
            # pair swaps (same or different position)
            for o1, o2 in itertools.combinations([i for i in ids if i not in protect], 2):
                p1, p2 = pool[o1]['pos'], pool[o2]['pos']
                for n1 in bypos[p1]:
                    if n1 in ids:
                        continue
                    for n2 in bypos[p2]:
                        if n2 in ids or n2 == n1:
                            continue
                        nid = [n1 if i == o1 else n2 if i == o2 else i for i in ids]
                        if sum(pool[i]['price'] for i in nid) > budget + 1e-9 or not legal(nid, pool):
                            continue
                        sc = score(nid, pool, gws)
                        if sc > cur + 1e-9 and (bestmove is None or sc > bestmove[0]):
                            bestmove = (sc, nid)
            if bestmove:
                cur, ids = bestmove
                improved = True
        if best is None or cur > best[0]:
            best = (cur, ids)
    return best


if __name__ == '__main__':
    t = time.time()
    print('HOLD blend 6gw', round(score(SQUAD, BLEND), 2), 'prior', round(score(SQUAD, PRIORP), 2),
          'gw6-8 avg', round(score(SQUAD, BLEND, range(3)) / 3, 2),
          'per gw', [round(best_xi(SQUAD, g, BLEND)[1], 2) for g in range(6)])
    xi, tot, cap = best_xi(SQUAD, 0, BLEND)
    print(' hold XI gw6:', fmt(xi), 'cap', BLEND[cap]['name'], round(tot, 2))
    cand = pruned(BLEND, 10)
    print('cand', len(cand), Counter(BLEND[c]['pos'] for c in cand))
    mode = sys.argv[1] if len(sys.argv) > 1 else 'singles'
    if mode == 'singles':
        allc = [i for i in BLEND if BLEND[i]['ep6'] > 1]
        r = transfers(1, allc)
        print('singles', len(r))
        for row in r[:40]:
            print(row[0], row[1], fmt(row[2]), '->', fmt(row[3]), 'bank', row[4], 'gw6-8', row[5])
        for o in [69, 237, 481, 423, 497]:
            best = [x for x in r if x[2][0] == o][:6]
            print('--- best exits for', BLEND[o]['name'])
            for row in best:
                print('  ', row[0], row[1], '->', fmt(row[3]), 'bank', row[4], 'gw6-8', row[5])
    elif mode == 'pairs':
        r = transfers(2, cand)
        print('pairs', len(r))
        for row in r[:30]:
            print(row[0], row[1], fmt(row[2]), '->', fmt(row[3]), 'bank', row[4], 'gw6-8', row[5])
    elif mode == 'triples':
        must = tuple(int(x) for x in sys.argv[2].split(',')) if len(sys.argv) > 2 else ()
        r = transfers(3, cand, must_out=must)
        print('triples', len(r), 'must_out', must)
        for row in r[:30]:
            print(row[0], row[1], fmt(row[2]), '->', fmt(row[3]), 'bank', row[4], 'gw6-8', row[5])
    elif mode == 'wc':
        budget = float(sys.argv[2]) if len(sys.argv) > 2 else 99.2
        for name, gws in [('6gw', range(6)), ('gw6-8', range(3)), ('gw8-11', range(2, 6))]:
            b = wildcard(BLEND, budget, gws, starts=8)
            ids = b[1]
            print(f'WC {name}: score {round(b[0],2)} avg/gw {round(b[0]/len(gws),2)} cost {round(sum(BLEND[i]["price"] for i in ids),1)} '
                  f'6gw {round(score(ids, BLEND),2)} prior {round(score(ids, PRIORP),2)} gw6-8avg {round(score(ids, BLEND, range(3))/3,2)}')
            for p in POS:
                print('   ', p, fmt([i for i in ids if BLEND[i]['pos'] == p]))
    print('elapsed', round(time.time() - t, 1))

